# -*- coding: utf-8 -*-
"""Module contains loggers responsible for creating sockets and saving data received from sockets to a specified file.

:copyright: Nokia Networks
:author: Pawel Chomicki
:contact: pawel.chomicki@nokia.com
"""
import asyncore
import threading

from .writer import FileWriter


class UDPLogger(threading.Thread):
    """A class for starting UDP sockets and saving data received by these sockets.

    :note: By default this Logger will create four listeners ('',51000), ('',51001), ('',51003), ('',50011).
           Use the configure_listeners method to modify these settings.

    :warning: Library waits for the is_running parameter to be True to be sure that all sockets have started.
    """
    def __init__(self, log_dir, log_name, listener_class, file_limit, add_line_number=False):
        """
        :param string log_dir:     Path to the directory where data should be saved.
        :param string log_name:    Name of the file where received data will be stored.
        :param listener_class:     Listener class which will be used to create a server and receive data.
        :param integer file_limit: Max. size of log file. 0 means unlimited.
        """
        super(UDPLogger, self).__init__()
        self.is_running = False

        self._ip = ''
        self._writer = FileWriter(log_dir, log_name, file_limit, add_line_number)
        self._ports = self._set_proper_ports()
        self._listeners = []
        self._listener_class = listener_class

    @property
    def log_path(self):
        """Path to the log file with received data.

        :note: Path has format log_dir/log_name.
        """
        return self._writer.log_path

    def clean_log_file(self):
        """Clean log file.

        :note: This method may be used to clean a file created by a previous syslog session.
        """
        self._writer.clean_log()

    def configure_listeners(self, listener_class=None, ip=None, ports=None):
        """Change listener settings.

        :param listener_class: Listener class which will be used to create a server and receive data.
        :param string ip:      IP address to bind.
        :param list   ports:   List of ports to bind.
        """
        self._listener_class = self._set_proper_listener_class(listener_class)
        self._ip = self._set_proper_ip(ip)
        self._ports = self._set_proper_ports(ports)

    def run(self):
        """Create listener and loop through sockets to receive data.

        :note: Method is executed when the thread is starting.
        """
        for port in self._ports:
            self._listeners.append(self._listener_class(self._ip, port, self.save_message))
        self.is_running = True
        self._data_size = 0
        self._loop_through_sockets()

    def stop(self):
        """Stop the logger and all listeners."""
        self.is_running = False
        for listener in self._listeners:
            listener.close()

    def save_message(self, msg):
        """Callback used to save received messages.

        :param string msg: Received message.
        """
        self._writer.write(msg)

    def _loop_through_sockets(self):
        while self.is_running:
            asyncore.loop(timeout=1)

    def _set_proper_listener_class(self, listener_class):
        if listener_class is None:
            return self._listener_class
        return listener_class

    def _set_proper_ip(self, ip):
        if ip is None:
            return ''
        return ip

    def _set_proper_ports(self, ports=None):
        if ports is None:
            return [51000, 51001, 51003, 50011]
        return ports
